#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

banner "Howy → Mac App Store"

# ── Stage 1 ────────────────────────────────────────────────────────────────
stage "App Store Connect: account and agreement"
say "A free app still needs the developer agreement to be active, or"
say "App Store Connect refuses the app and TestFlight stays off."
open_url "https://appstoreconnect.apple.com/business"
step "Sign in with your developer Apple ID."
step "Look at 'Agreements': the Apple Developer Program License Agreement"
step "must show as Active. If a banner asks you to accept new terms, accept."
note "No banner and an Active agreement means there is nothing to do here."
pause "Agreement is active? Press Enter."

# ── Stage 2 ────────────────────────────────────────────────────────────────
stage "Developer portal: App IDs and the group.howy app group"
say "Xcode's automatic signing has probably registered these already;"
say "this stage only verifies they exist, with the right capabilities."
open_url "https://developer.apple.com/account/resources/identifiers/list"
step "In the list of Identifiers (type: App IDs), find lueddemann.howy"
step "and lueddemann.howy.widgets. Open lueddemann.howy."
step "Check the capability list: 'App Groups' and 'iCloud' must be ticked."
step "Under iCloud, iCloud.lueddemann.howy should be the assigned container."
step "Back in the list, switch the type filter (top right) to 'App Groups'"
step "and check that group.howy is listed."
warn "If anything is missing, don't create it by hand yet; tell Claude"
warn "instead, because a mismatch here usually means a signing problem."
pause "Both App IDs and the group exist? Press Enter."

# ── Stage 3 ────────────────────────────────────────────────────────────────
stage "CloudKit Console: deploy the schema to Production"
say "Store builds talk to the Production environment, which is empty"
say "until the schema (the record types) is copied over from Development."
warn "Deploying is one-way: record types and fields can never be deleted"
warn "from Production again. Your Development data itself is NOT copied."
open_url "https://icloud.developer.apple.com/dashboard/"
step "The start page has no container picker: click the 'CloudKit Database'"
step "card first (or open icloud.developer.apple.com/dashboard/database)."
step "Top left: pick the container iCloud.lueddemann.howy."
step "Make sure the environment switch says 'Development'."
step "Go to the Schema section and open 'Record Types': you should see"
step "CD_Todo, CD_TodoEvent and CD_StoredAttachment (plus CD_ metadata types)."
step "Find 'Deploy Schema Changes…' (bottom of the Schema sidebar)."
step "The review sheet lists everything that will be created in Production."
if confirm "Does the review list the CD_ record types above?"; then
  step "Click Deploy."
  step "Switch the environment to 'Production' and check the same record"
  step "types are now listed there."
  pause "Deployed and verified? Press Enter."
else
  warn "Stop here and tell Claude what the review sheet shows instead."
  exit 1
fi

# ── Stage 4 ────────────────────────────────────────────────────────────────
stage "App Store Connect: create the app"
open_url "https://appstoreconnect.apple.com/apps"
step "Click the + button → 'New App'."
note "Skip this stage if Howy already exists there (a later release)."
step "Platform: macOS."
step "Name: 'Howy' — names are unique store-wide, so if it's taken,"
step "pick a variant (e.g. 'Howy — Eisenhower Matrix'). Only the store"
step "listing name changes; the app itself stays Howy."
step "Primary language: English."
step "Bundle ID: pick lueddemann.howy from the dropdown."
step "SKU: 'howy' (an internal label, never shown to anyone)."
step "User access: Full Access."
step "Click Create."
step "The first store version is always called 1.0: click it and change"
step "it to the version in project.yml (MARKETING_VERSION)."
note "Screenshots, description and pricing can wait; the app record is"
note "enough for uploading builds and TestFlight."
pause "App record created? Press Enter."

# ── Stage 5 ────────────────────────────────────────────────────────────────
stage "Xcode: archive and upload the first build"
say "Opening the project; the upload happens from Xcode's Organizer."
( cd "$(dirname "$0")/.." && command -v xed >/dev/null 2>&1 && xed . ) || true
step "In Xcode, select the 'Howy' scheme and destination 'My Mac'."
warn "Each upload needs a NEW build number: raise CURRENT_PROJECT_VERSION"
warn "in project.yml and run 'xcodegen generate' before archiving."
step "Menu: Product → Archive (builds Release; takes a minute)."
warn "Ignore any 'Xcode Cloud' / 'Select Product' sheet: that is a"
warn "different service. Cancel it."
step "The Organizer window opens with the new archive. Click"
step "'Distribute App' → 'App Store Connect' → Upload/Distribute."
step "Keep every default (automatic signing). Xcode may ask to create an"
step "'Apple Distribution' certificate: allow it."
step "Wait for 'Upload Successful'."
note "The build appears under the TestFlight tab (not the App Store page)"
note "once processed. App Store Connect processes it server-side; you get a"
note "mail when it's done, usually within the hour. The encryption"
note "question is already answered by a key in the Info.plist."
pause "Upload finished? Press Enter."

# ── Stage 6 ────────────────────────────────────────────────────────────────
stage "TestFlight: install the store build (optional check)"
say "This proves the whole production path: signing, sandbox, widget"
say "and the Production CloudKit environment."
warn "A TestFlight build syncs with the PRODUCTION environment, so it"
warn "won't see the todos of your dev builds (Development environment)."
warn "It re-uploads this Mac's local store into Production on first run;"
warn "nothing is lost locally. Don't mix it with dev builds day-to-day:"
warn "test, then go back to your dev build until the real store release."
if confirm "Run the TestFlight check now?"; then
  open_url "https://appstoreconnect.apple.com/apps"
  step "Open Howy → TestFlight tab. The processed build is listed; answer"
  step "any remaining compliance prompt with 'no encryption beyond Apple's'."
  step "Add yourself under Internal Testing (create a group, add your"
  step "Apple ID as tester)."
  step "On the Mac: install 'TestFlight' from the Mac App Store, sign in,"
  step "accept the Howy invitation (mail), install and launch the build."
  pause "Build runs from TestFlight? Press Enter."
else
  note "Skipped; you can run this stage any time after a build is processed."
fi

finish
note "Next store releases only need: bump version, deploy any NEW schema"
note "changes in the CloudKit Console (stage 3), archive and upload."
